const vec3 sky_colour = vec3(0.4, 0.7, 0.9);
const vec3 ground_colour = vec3(0.4, 0.4, 0.4);

const float pi = 3.14159;

struct Ray {
    vec3 o; // origin
    vec3 n; // direction
};

vec2 ground_plane_intersect(Ray r)
{
    float s = -r.o.y / r.n.y;
    return (r.o + s*r.n).xz;
}

float grid(float x, float width, float height, float spacing)
{
    float shift_x = x - spacing/2.;

    return height / (1. + pow((mod(shift_x, spacing) - spacing/2.)/width, 2.));
}

float parabola(vec2 u)
{
    return .01*(u.y*u.y+10.) / (.1 + pow(u.y - u.x*u.x, 2.));
}

float hyperbola(vec2 u)
{
    return .01*(u.y*u.y+10.) / (.1 + pow(u.y*u.y - u.x*u.x - 1., 2.));
}

vec3 cast_ray_radial(vec2 uv, float vfov)
{
    float theta = length(uv)*vfov*pi/180.;
    float phi = atan(uv.y/uv.x);

    return vec3(sin(theta)*uv,cos(theta));
}

Ray cast_ray(vec3 cam_pos, vec3 cam_dir, vec2 uv, float depth)
{
    // cast rays from a source cam_pos in the scene relative to image plane
    vec3 o = cam_pos;

    vec3 screen_x = normalize(cross(vec3(0.,1.,0.), cam_dir));
    vec3 screen_y = cross(cam_dir, screen_x);

    vec3 n = normalize(uv.x*screen_x + uv.y*screen_y + depth*cam_dir);

    return Ray(o, n);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord - iResolution.xy/2.)/iResolution.y;

    vec3 col = sky_colour;

    vec2 mouse = (iMouse.xy - vec2(iResolution.x/2., iResolution.y))/iResolution.y;

    float theta_dir = pi/2.*(1. + clamp(0., 1., 1.1*mouse.y*mouse.y));

    float phi_dir = mouse.x;

    vec3 cam_dir = vec3(sin(theta_dir)*sin(phi_dir), cos(theta_dir), sin(theta_dir)*cos(phi_dir));

    vec3 cam_pos = -50.*cam_dir;

    Ray view_ray = cast_ray(cam_pos, cam_dir, uv, 3.);

    if (view_ray.n.y < 0.)
    {
        col = ground_colour;

    	vec2 xz = ground_plane_intersect(view_ray);

        col -= grid(xz.x, 0.02, .4, 1.);
        col -= grid(xz.y, 0.02, .4, 1.);

        col.r += parabola(xz);

        col.b += hyperbola(xz);
    }

    // Output to screen
    fragColor = vec4(col, 1.0);
}
